actions.script:
if (screenSecurity != null && screenSecurity !== '') {
    if (!['off', 'encrypted', 'app'].includes(String(screenSecurity))) { ec.message.addError(ec.l10n.localize('Choose off, in encrypted rooms or everywhere')); return }
    ec.user.setPreference('CHAT_SCREEN_SECURITY', String(screenSecurity))
}
if (fromForm || (otpDelete != null && otpDelete !== '')) ec.user.setPreference('CHAT_OTP_DELETE', otpDelete === 'Y' || otpDelete === 'true' || otpDelete === true ? 'Y' : 'N')
